1633	static void vg_offline_win_push(vg_sensor_t * s, bool failed)
1634	{
1635	    uint8_t mask = (uint8_t)(1u << (s->failwin_pos % VG_OFFLINE_WIN_TICKS));
1636	
1637	    if(s->failwin_bits & mask) {
1638	        s->failwin_fails--;
1639	    }
1640	    if(failed) {
1641	        s->failwin_bits |= mask;
1642	        s->failwin_fails++;
1643	    }
1644	    else {
1645	        s->failwin_bits &= (uint8_t)~mask;
1646	    }
1647	    s->failwin_pos = (uint8_t)((s->failwin_pos + 1) % VG_OFFLINE_WIN_TICKS);
1648	}
1649	
1650	static bool vg_offline_win_down(const vg_sensor_t * s)
1651	{
1652	    uint8_t need = VG_OFFLINE_MIN_FAILS;
1653	
1654	    if(s->fail_n > need) {
1655	        need = s->fail_n;
1656	    }
1657	    if(need > VG_OFFLINE_WIN_TICKS) {
1658	        need = VG_OFFLINE_WIN_TICKS;
1659	    }
1660	    return s->failwin_fails >= need;
1661	}
