619	static FAR void *vg_hmi_acq_thread(FAR void *arg)
620	{
621	  static int live_ok_logs;
622	  (void)arg;
623	
624	  for(;;) {
625	    struct vg_discover_summary live;
626	    int i;
627	    int n;
628	    int ok = 0;
629	    float a1 = 0.0f;
630	
631	    if(board_bus_busy()) {
632	      usleep(200000);
633	      continue;
634	    }
635	
636	    n = vg_live_points_copy(&live);
637	    if(n < 0) {
638	      n = 0;
639	    }
640	    if(n > VG_LIVE_MAX) {
641	      n = VG_LIVE_MAX;
642	    }
643	
644	    if(n <= 0) {
645	      g_live_n = 0;
646	      write_live_snapshot(&live, 0);
647	      usleep(500000);
648	      continue;
649	    }
650	
651	    if(vg_bus_try_lock() != 0) {
652	      usleep(200000);
653	      continue;
654	    }
655	
656	    {
657	      uint16_t raws[VG_LIVE_MAX];
658	      uint8_t oks[VG_LIVE_MAX];
659	      int rc;
660	
661	      rc = vg_discover_poll_points(vg_hmi_rs485_devpath(),
662	                                   CONFIG_VG_HMI_DISCOVER_BAUD,
663	                                   live.points, n,
664	                                   raws, oks,
665	                                   CONFIG_VG_HMI_DISCOVER_INTER_MS);
666	      vg_bus_unlock();
667	      if(rc != 0) {
668	        printf("vghmi: live open failed rc=%d\n", rc);
669	        for(i = 0; i < n; i++) {
670	          g_live_on[i] = 0;
671	        }
672	        g_live_n = n;
673	        write_live_snapshot(&live, n);
674	        usleep(500000);
675	        continue;
676	      }
677	
678	      for(i = 0; i < n; i++) {
679	        FAR const struct vg_point_entry *p = &live.points[i];
680	        int signed_v = (strcmp(p->dtype, "uint16") != 0);
681	
682	        if(oks[i]) {
683	          float v = signed_v ? ((float)(int16_t)raws[i] * p->scale)
684	                             : ((float)raws[i] * p->scale);
685	          g_live_v[i] = v;
686	          g_live_on[i] = 1;
687	          ok++;
688	          if(p->addr == 1 && p->reg == 0) {
689	            a1 = v;
690	          }
691	        }
692	        else {
693	          g_live_on[i] = 0;
694	        }
695	      }
696	    }
697	
698	    g_live_n = n;
699	    write_live_snapshot(&live, n);
700	    if(ok > 0) {
701	      if(live_ok_logs < 8) {
702	        printf("vghmi: live ok=%d/%d a1=%.1f\n", ok, n, (double)a1);
703	        live_ok_logs++;
704	      }
705	    }
706	    else if(live_ok_logs == 0) {
707	      printf("vghmi: live ok=0/%d a1=0.0\n", n);
708	      live_ok_logs = -1;
709	    }
710	    usleep(200000);
711	  }
712	
713	  return NULL;
714	}
