716	void vg_ui_backend_acq_start(void)
717	{
718	  pthread_t tid;
719	  pthread_attr_t attr;
720	  struct vg_discover_summary live;
721	  int n;
722	
723	  if(g_acq_started) {
724	    return;
725	  }
726	
727	  g_acq_started = true;
728	  pthread_attr_init(&attr);
729	  pthread_attr_setstacksize(&attr, VG_HMI_SCAN_STACKSIZE);
730	  if(pthread_create(&tid, &attr, vg_hmi_acq_thread, NULL) != 0) {
