299	int vg_discover_poll_points(FAR const char *devpath, int baud,
300	                            FAR const struct vg_point_entry *pts, int n,
301	                            FAR uint16_t *raw, FAR uint8_t *ok_out,
302	                            int inter_ms)
303	{
304	  struct vg_disc_nmbs s;
305	  int i;
306	
307	  (void)baud;
308	
309	  if (devpath == NULL || pts == NULL || raw == NULL ||
310	      ok_out == NULL || n <= 0)
311	    {
312	      return -EINVAL;
313	    }
314	
315	  if (vg_disc_nmbs_open(&s, devpath) != 0)
316	    {
317	      return -errno;
318	    }
319	
320	  for (i = 0; i < n; i++)
321	    {
322	      nmbs_error err;
323	      uint16_t qty = pts[i].qty;
324	      uint16_t tmp[VG_DISC_MAX_REGS];
325	
326	      raw[i] = 0;
327	      ok_out[i] = 0;
328	      if (pts[i].addr == 0)
329	        {
330	          continue;
331	        }
332	
333	      if (qty < 1)
334	        {
335	          qty = 1;
336	        }
337	
338	      if (qty > VG_DISC_MAX_REGS)
339	        {
340	          qty = VG_DISC_MAX_REGS;
341	        }
342	
343	      if (pts[i].fc == 4)
344	        {
345	          err = vg_disc_read_input(&s, pts[i].addr, pts[i].reg, qty, tmp);
346	        }
347	      else
348	        {
349	          err = vg_disc_read_holding(&s, pts[i].addr, pts[i].reg, qty, tmp);
350	        }
351	
352	      if (err == NMBS_ERROR_NONE)
353	        {
354	          raw[i] = tmp[0];
355	          ok_out[i] = 1;
356	        }
357	
358	      if (inter_ms > 0 && i + 1 < n)
359	        {
360	          usleep((useconds_t)inter_ms * 1000);
361	        }
362	    }
363	
364	  vg_disc_nmbs_close(&s);
365	  return 0;
366	}
