94	    int w;
95	
96	    w = lv_snprintf(out, n, "%d:%u|", (int)vg_model_get_home_filter(), (unsigned)cnt);
97	    if(w < 0) {
98	        out[0] = '\0';
99	        return;
100	    }
101	    used = (size_t)w;
