101	static int write_seed_file(const char *path, const char *body)
102	{
103	  size_t len = strlen(body);
104	  bool same = false;
105	  struct stat st;
106	  int fd;
107	
108	  /* Refresh in place when eMMC already holds an older seed text, so
109	   * firmware-side wording changes land on previously provisioned boards. */
110	
111	  fd = open(path, O_RDONLY);
112	  if (fd >= 0)
113	    {
114	      if (fstat(fd, &st) == 0 && st.st_size == (off_t)len)
115	        {
116	          char chunk[128];
117	          size_t off;
118	
119	          same = true;
120	          for (off = 0; off < len && same; off += sizeof(chunk))
121	            {
122	              size_t want = len - off;
123	              ssize_t got;
124	
125	              if (want > sizeof(chunk))
126	                {
127	                  want = sizeof(chunk);
128	                }
129	
130	              got = read(fd, chunk, want);
131	              if (got != (ssize_t)want ||
132	                  memcmp(chunk, body + off, want) != 0)
133	                {
134	                  same = false;
135	                }
136	            }
137	        }
138	
139	      close(fd);
140	      if (same)
141	        {
142	          return 0;
143	        }
144	    }
145	
146	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
147	  if (fd < 0)
