42	/* ── Content check ────────────────────────────────────────────── */
43	
44	/**
45	 * Check if HEARTBEAT.md has actionable content.
46	 * Returns true if any line is NOT:
47	 *   - empty / whitespace-only
48	 *   - a markdown header (starts with #)
49	 *   - a completed checkbox (- [x] or * [x])
50	 */
51	static bool heartbeat_has_tasks(void)
52	{
53	    FILE *f = fopen(AGENT_HEARTBEAT_FILE, "r");
54	    if (!f) {
55	        return false;
56	    }
57	
58	    char line[256];
59	    bool found_task = false;
60	
61	    while (fgets(line, sizeof(line), f)) {
62	        /* Skip leading whitespace */
63	        const char *p = line;
64	        while (*p && isspace((unsigned char)*p)) {
65	            p++;
66	        }
67	
68	        /* Skip empty lines */
69	        if (*p == '\0') {
70	            continue;
71	        }
72	
73	        /* Skip markdown headers */
74	        if (*p == '#') {
75	            continue;
76	        }
77	
78	        /* Skip completed checkboxes: "- [x]" or "* [x]" */
79	        if ((*p == '-' || *p == '*') && *(p + 1) == ' ' && *(p + 2) == '[') {
80	            char mark = *(p + 3);
81	            if ((mark == 'x' || mark == 'X') && *(p + 4) == ']') {
82	                continue;
83	            }
84	        }
85	
86	        /* Found an actionable line */
87	        found_task = true;
88	        break;
89	    }
90	
91	    fclose(f);
92	    return found_task;
93	}
