97	static bool heartbeat_send(void)
98	{
99	    if (!heartbeat_has_tasks()) {
100	        return false;
101	    }
102	
103	    agent_msg_t msg;
104	    memset(&msg, 0, sizeof(msg));
105	    strncpy(msg.channel, AGENT_CHAN_SYSTEM, sizeof(msg.channel) - 1);
106	    strncpy(msg.chat_id, "heartbeat", sizeof(msg.chat_id) - 1);
107	    msg.content = strdup(HEARTBEAT_PROMPT);
108	
109	    if (!msg.content) {
110	        syslog(LOG_ERR, "[%s] Failed to allocate heartbeat prompt\n", TAG);
111	        return false;
112	    }
113	
114	    int err = message_bus_push_inbound(&msg);
115	    if (err != OK) {
116	        syslog(LOG_WARNING, "[%s] Failed to push heartbeat message: %s\n", TAG, strerror(errno));
117	        free(msg.content);
118	        return false;
119	    }
120	
121	    syslog(LOG_INFO, "[%s] Triggered agent check\n", TAG);
122	
123	    /* Lazy-loop builds (VelaGuard HMI) only start agent_loop on demand;
124	     * make sure the queued heartbeat prompt actually gets consumed. */
125	    agent_loop_ensure_started();
126	    return true;
127	}
