Design:

```c
static void *heartbeat_thread(void *arg)
{
    (void)arg;

    while (s_heartbeat_running) {
        /* Slice the interval sleep so a poke file can trigger an immediate
         * check (on-demand daily report from the HMI). */
        int waited = 0;
        int interval_s = AGENT_HEARTBEAT_INTERVAL_MS / 1000;

        while (s_heartbeat_running && waited < interval_s) {
            sleep(5);
            waited += 5;
            if (access(AGENT_HEARTBEAT_POKE_FILE, F_OK) == 0) {
                unlink(AGENT_HEARTBEAT_POKE_FILE);
                break;
            }
        }
        if (!s_heartbeat_running) {
            break;
        }
        heartbeat_send();
    }

    return NULL;
}
```

